const { requireLogin } = require("./auth");
const run = (headers) => new Promise((r) => {
  const res = { status(c){ this.code=c; return this; }, json(b){ r({code:this.code||200, body:b}); } };
  requireLogin({ headers }, res, () => r({ code: 200, body: "next()" }));
});
(async () => {
  console.log("no creds      ", await run({}));
  console.log("cookie        ", await run({ cookie: "session=abc" }));
  console.log("good token    ", await run({ authorization: "Bearer s3cret" }));
  console.log("wrong token   ", await run({ authorization: "Bearer nope" }));
  console.log("short token   ", await run({ authorization: "Bearer s" }));
  console.log("empty bearer  ", await run({ authorization: "Bearer " }));
})();
'

